#!/usr/bin/env python3
"""Compressed capture transport, CSV framing and discovery bucket paths.

Campaign path: ``capture_records`` turns the base64 chunk transport of every
capture into typed records plus rejected ``[capture, ordinal]`` indices, and
``roles``/``lease_states`` bucket live ICMP evidence into the internal and
external discovery sets with their earliest causal witnesses.

Legacy CLI (unchanged development tool, ZMap6 flavoured): group responses by
/64 network and classify each responder as internal (the probed address
answered itself) or external (a different address answered), skipping aliased
networks::

    classify_responses.py aliases.txt zmap-output.csv.zst > networks.jsonl
"""
import argparse
import csv
import io
import ipaddress
import json

import zstandard as zstd

from common import COLUMNS, CaptureError, decode64
from ledger import parse_record

HEADER = list(COLUMNS)
FIELD_BYTES = 131072
RECORD_LIMIT = 200000
DECODED_LIMIT = 32 * 1024 ** 2
DECOMPRESSED_LIMIT = 128 * 1024 ** 2
WINDOW_LIMIT = 128 * 1024 ** 2
SKIPPABLE_LOW = 0x184d2a50
SKIPPABLE_HIGH = 0x184d2a5f
FRAME_MAGIC = 0xfd2fb528


class BoundedReader(io.RawIOBase):
    """Raw wrapper that enforces a shared decompressed byte budget."""

    def __init__(self, source, budget):
        self.source = source
        self.budget = budget

    def readable(self):
        return True

    def readinto(self, buffer):
        block = self.source.read(min(len(buffer), self.budget[0] + 1))
        self.budget[0] -= len(block)
        if self.budget[0] < 0:
            raise CaptureError('decompressed byte budget')
        buffer[:len(block)] = block
        return len(block)


def complete_frames(data):
    """Validate complete dictionary-free bounded-window Zstandard framing."""
    at = 0
    while at < len(data):
        if at + 4 > len(data):
            raise CaptureError('truncated Zstandard magic')
        magic = int.from_bytes(data[at:at + 4], 'little')
        if SKIPPABLE_LOW <= magic <= SKIPPABLE_HIGH:
            if at + 8 > len(data):
                raise CaptureError('truncated skippable frame')
            size = int.from_bytes(data[at + 4:at + 8], 'little')
            at += 8 + size
            if at > len(data):
                raise CaptureError('truncated skippable frame')
            continue
        if magic != FRAME_MAGIC or at + 5 > len(data):
            raise CaptureError('invalid Zstandard frame')
        flag = data[at + 4]
        if flag & 0x08:
            raise CaptureError('reserved Zstandard frame bit')
        single = bool(flag & 0x20)
        dictionary = (0, 1, 2, 4)[flag & 3]
        content = (1 if single else 0, 2, 4, 8)[flag >> 6]
        header = 5 + (not single) + dictionary + content
        if at + header > len(data):
            raise CaptureError('truncated Zstandard header')
        try:
            params = zstd.get_frame_parameters(data[at:at + header])
        except zstd.ZstdError as exc:
            raise CaptureError('invalid Zstandard frame header') from exc
        if params.dict_id:
            raise CaptureError('dictionary-backed Zstandard frame')
        if params.window_size > WINDOW_LIMIT:
            raise CaptureError('oversized Zstandard window')
        at += header
        while True:
            if at + 3 > len(data):
                raise CaptureError('truncated Zstandard block')
            block = int.from_bytes(data[at:at + 3], 'little')
            at += 3
            kind = (block >> 1) & 3
            size = block >> 3
            if kind == 3:
                raise CaptureError('reserved Zstandard block type')
            at += 1 if kind == 1 else size
            if at > len(data):
                raise CaptureError('truncated Zstandard block')
            if block & 1:
                break
        if flag & 4:
            at += 4
        if at > len(data):
            raise CaptureError('truncated Zstandard checksum')


def stream_csv(path, encoding='zstd', budget=None, logical_records=False):
    """Legacy development stream over a file path."""
    with open(path, 'rb') as handle:
        reader = (zstd.ZstdDecompressor().stream_reader(handle, read_across_frames=True)
                  if encoding == 'zstd' else handle)
        bounded = io.BufferedReader(BoundedReader(reader, budget)) if budget is not None else reader
        with io.TextIOWrapper(bounded, encoding='utf-8', newline='') as text:
            if logical_records:
                yield from csv.reader(text, strict=True)
            else:
                for line in text:
                    if line.startswith('saddr'):
                        continue
                    yield line


def logical_rows(data, encoding, budget):
    """Yield the logical CSV records of one decoded capture byte string."""
    source = io.BytesIO(data)
    if encoding == 'zstd':
        reader = zstd.ZstdDecompressor().stream_reader(source, read_across_frames=True,
                                                       closefd=False)
    else:
        reader = source
    bounded = io.BufferedReader(BoundedReader(reader, budget))
    with io.TextIOWrapper(bounded, encoding='utf-8', newline='') as text:
        yield from csv.reader(text, strict=True)


def capture_records(context, lookup):
    """Decode every capture and split it into typed records and rejected indices."""
    csv.field_size_limit(FIELD_BYTES)
    records = []
    rejected = []
    decoded = 0
    count = 0
    budget = [DECOMPRESSED_LIMIT]
    for number, capture in enumerate(context['captures']):
        blocks = [decode64(chunk, CaptureError) for chunk in capture['chunks']]
        decoded += sum(map(len, blocks))
        if decoded > DECODED_LIMIT:
            raise CaptureError('decoded byte budget')
        data = b''.join(blocks)
        del blocks
        if capture['encoding'] == 'zstd':
            complete_frames(data)
        rows = logical_rows(data, capture['encoding'], budget)
        try:
            if next(rows, None) != HEADER:
                raise CaptureError('invalid CSV header')
            for ordinal, values in enumerate(rows):
                count += 1
                if count > RECORD_LIMIT:
                    raise CaptureError('capture record budget')
                for field in values:
                    if not field.isascii() and len(field.encode('utf-8')) > FIELD_BYTES:
                        raise CaptureError('capture field budget')
                try:
                    records.append(parse_record(values, context, lookup))
                except CaptureError:
                    raise
                except Exception:
                    rejected.append([number, ordinal])
        except (UnicodeError, csv.Error, zstd.ZstdError, EOFError, OSError) as exc:
            raise CaptureError('invalid capture encoding') from exc
        finally:
            try:
                rows.close()
            except Exception:
                pass
        del data
    return records, rejected


def record_response(networks, key, target, responder, same_is_internal=True):
    """Legacy /64 bucket helper used by the development CLI below."""
    bucket = networks.setdefault(key, {'network': key, 'internal': set(), 'external': set()})
    if target == responder:
        if not same_is_internal:
            return None
        role = 'internal'
    else:
        role = 'external'
    bucket[role].add(responder)
    return role


def roles(icmp_rows):
    """Raw lease discovery buckets ``{lease: [internal, external, aliased]}``.

    A positive self echo of a planned low target is internal evidence; any
    non-timeout low probe answered by a different address is external evidence;
    a self error contributes neither.  A positive self echo of any canary marks
    the whole lease aliased, and no other canary response contributes a role.
    Each role maps a responder address to its earliest supporting live event.
    """
    found = {}
    for content in icmp_rows:
        _, lease, event, probe, target, responder, result = content
        bucket = found.get(lease)
        if bucket is None:
            bucket = found[lease] = [{}, {}, False]
        if probe[-2:] == '/c':
            if result == 'echo' and responder == target:
                bucket[2] = True
            continue
        if result == 'timeout':
            continue
        if responder == target:
            if result != 'echo':
                continue
            seen = bucket[0]
            key = target
        else:
            seen = bucket[1]
            key = responder
        witness = seen.get(key)
        if witness is None or event < witness:
            seen[key] = event
    return found


def lease_states(leases, lows, moment, found):
    """Lease state priority with clean roles, raw conflicts and unresolved lows."""
    states = {}
    for lease, row in leases.items():
        if moment < row['start'] or moment >= row['end']:
            states[lease] = ('inactive', {}, {}, [], [])
            continue
        evidence = found.get(lease)
        if evidence is None:
            internal = {}
            external = {}
            aliased = False
        else:
            internal, external, aliased = evidence
        conflicts = sorted(set(internal) & set(external))
        if aliased:
            state = 'alias'
        elif conflicts:
            state = 'conflict'
        else:
            state = 'usable'
        if state == 'usable':
            clean_internal = internal
            clean_external = external
        else:
            clean_internal = {}
            clean_external = {}
        unresolved = sorted(lows[lease] - set(clean_internal) - set(clean_external))
        states[lease] = (state, clean_internal, clean_external, conflicts, unresolved)
    return states


def classify(records, leases, at, low):
    """Legacy entry: reconciled lease discovery roles for one query time."""
    found = roles([row[3] for row in records
                   if row[0] <= at and row[3][0] == 'i'])
    return lease_states(leases, low, at, found)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument('aliases_file',
                        help='text file of aliased /64 prefixes (4 colon groups)')
    parser.add_argument('zmap_csv',
                        help='ZMap6 output CSV.zst (saddr,...,responder,...)')
    args = parser.parse_args()

    aliases = set()
    with open(args.aliases_file) as handle:
        for line in handle:
            aliases.add(line.strip())

    networks = {}
    for row in stream_csv(args.zmap_csv):
        fields = row.split(',')
        if len(fields) < 2:
            continue
        target, responder = fields[0], fields[1]
        try:
            exploded = ipaddress.IPv6Address(target).exploded
        except (ipaddress.AddressValueError, ValueError):
            continue
        net64 = ':'.join(exploded.split(':')[0:4])
        if net64 in aliases:
            continue
        record_response(networks, net64, target, responder)

    for entry in networks.values():
        entry['internal'] = sorted(entry['internal'])
        entry['external'] = sorted(entry['external'])
        print(json.dumps(entry))


if __name__ == '__main__':
    main()
